import java.util.*;

public class SolutionTest {
    public static void main(String[] args) {
        prefix("0", "0");
        prefix("-2147483648", "-2147483648");
        prefix("2147483647", "2147483647");
        prefix(" add ( 1 , mul( 2, neg(3) ) ) ", "ADD(1,MUL(2,NEG(3)))");
        prefix("neg(add(-2,5))", "NEG(ADD(-2,5))");

        infix("0", "0");
        infix("-2147483648", "-2147483648");
        infix("1 + 2 * 3", "ADD(1,MUL(2,3))");
        infix("(1 + 2) * 3", "MUL(ADD(1,2),3)");
        infix("10 + 20 + 30", "ADD(ADD(10,20),30)");
        infix("2 * 3 * 4", "MUL(MUL(2,3),4)");
        infix("-2 * -(3 + 4) + 5", "ADD(MUL(NEG(2),NEG(ADD(3,4))),5)");
        infix("--5", "NEG(NEG(5))");
        infix("1+-2", "ADD(1,NEG(2))");
        infix(" \t ( 7 ) \n", "7");

        invalidPrefix(null);
        invalidPrefix("");
        invalidPrefix("   ");
        invalidPrefix("2147483648");
        invalidPrefix("-2147483649");
        invalidPrefix("add(1)");
        invalidPrefix("add(1,)");
        invalidPrefix("add(,2)");
        invalidPrefix("add(1,2,3)");
        invalidPrefix("mul(1 2)");
        invalidPrefix("neg()");
        invalidPrefix("sub(1,2)");
        invalidPrefix("1 trailing");
        invalidPrefix("add(1,2");

        invalidInfix(null);
        invalidInfix("");
        invalidInfix(" \n");
        invalidInfix("2147483648");
        invalidInfix("-2147483649");
        invalidInfix("1+");
        invalidInfix("*2");
        invalidInfix("1 2");
        invalidInfix("()");
        invalidInfix("(1+2");
        invalidInfix("1+2)");
        invalidInfix("1/**2");
        invalidInfix("hello");

        String mutableReferenceCheck = new String("4+5");
        Solution.Expr parsed = Solution.parseInfix(mutableReferenceCheck);
        eq("ADD(4,5)", parsed.toString());
        eq("ADD(4,5)", parsed.toString());
    }

    private static void prefix(String input, String expected) {
        Solution.Expr expression = Solution.parsePrefix(input);
        check(expression != null, "prefix parse returned null");
        eq(expected, expression.toString());
    }

    private static void infix(String input, String expected) {
        Solution.Expr expression = Solution.parseInfix(input);
        check(expression != null, "infix parse returned null");
        eq(expected, expression.toString());
    }

    private static void invalidPrefix(String input) {
        expect(IllegalArgumentException.class, () -> Solution.parsePrefix(input));
    }

    private static void invalidInfix(String input) {
        expect(IllegalArgumentException.class, () -> Solution.parseInfix(input));
    }

    private static void eq(Object expected, Object actual) {
        if (!Objects.equals(expected, actual))
            throw new AssertionError("expected <" + expected + "> but was <" + actual + ">");
    }

    private static void check(boolean condition, String message) {
        if (!condition) throw new AssertionError(message);
    }

    private static void expect(Class<? extends Throwable> type, Runnable action) {
        try {
            action.run();
        } catch (Throwable error) {
            if (type.isInstance(error)) return;
            throw new AssertionError("expected " + type.getName() + " but got " + error, error);
        }
        throw new AssertionError("expected " + type.getName());
    }
}

